//! Golden vectors for part 4 (communications), all generated by
//! `apps/backend/tests-golden/domain/gen_domain4.py` from the Python implementation. Nothing is
//! normalized: every value is compared exactly.

mod common;

use base64::Engine;
use indexmap::IndexMap;
use serde_json::{Map, Value};
use sha2::{Digest, Sha256};
use ss_core::Contract;
use ss_domain::communications::call_script::{build_script, describe, extract};
use ss_domain::communications::{call_payload, detect_escalation};
use ss_domain::contracts::communications::{
    CallQuestion, CallSession, CallState, HandoffStatus, OwnerHandoffRequest, StructuredFinding,
};
use ss_domain::contracts::infrastructure::InfrastructureAssessment;
use ss_domain::integrations::telnyx::{decode_client_state, encode_client_state};
