use ss_domain::py::{self, PyRegex};
use uuid::Uuid;

fn g(name: &str) -> Value {
    common::golden(&format!("domain/{name}"))
}

fn s(v: &Value) -> &str {
    v.as_str().expect("string")
}

#[test]
fn every_state_pair_matches_python() {
    let doc = g("part4_comms.json");
    let pairs = &doc["state_pairs"];
    let calls = pairs["call"].as_array().unwrap();
    assert_eq!(calls.len(), 144);
    let mut allowed = 0;
    for p in calls {
        let from: CallState = s(&p["from"]).parse().unwrap();
        let to: CallState = s(&p["to"]).parse().unwrap();
        let mut c = CallSession::new(Uuid::nil(), Uuid::nil(), IndexMap::new(), Uuid::nil());
        c.state = from;
        match (c.transition(to), p["ok"].as_bool().unwrap()) {
            (Ok(n), true) => {
                assert_eq!(n.state, to);
                allowed += 1;
            }
            (Err(e), false) => assert_eq!(e.to_string(), s(&p["error"]), "{from} -> {to}"),
            (r, ok) => panic!("{from} -> {to}: Rust {r:?}, Python ok={ok}"),
        }
    }
    let handoffs = pairs["handoff"].as_array().unwrap();
    assert_eq!(handoffs.len(), 36);
    for p in handoffs {
        let from: HandoffStatus = s(&p["from"]).parse().unwrap();
        let to: HandoffStatus = s(&p["to"]).parse().unwrap();
        let mut h = OwnerHandoffRequest::from_json_value(serde_json::json!({
            "call_id": Uuid::nil(), "project_id": Uuid::nil(), "reason": "FINANCIAL_DETAILS",
            "question": "q", "owner_id": Uuid::nil(), "expires_at": "2026-11-14T12:00:00Z",
        }))
        .unwrap();
        h.status = from;
        match (h.transition(to), p["ok"].as_bool().unwrap()) {
            (Ok(n), true) => {
                assert_eq!(n.status, to);
                allowed += 1;
            }
            (Err(e), false) => assert_eq!(e.to_string(), s(&p["error"]), "{from} -> {to}"),
            (r, ok) => panic!("{from} -> {to}: Rust {r:?}, Python ok={ok}"),
        }
    }
    assert_eq!(
        allowed,
        26 + 6,
        "26 call and 6 handoff transitions are allowed"
    );
}

#[test]
fn build_script_matches_python() {
    let doc = g("part4_comms.json");
    let cases = doc["scripts"].as_array().unwrap();
    assert!(cases.len() >= 30);
    let mut pipeline = 0;
    for c in cases {
        let name = s(&c["name"]);
        let assessments: Vec<InfrastructureAssessment> = c["assessments"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| InfrastructureAssessment::from_json_value(a.clone()).expect(name))
            .collect();
        let script = build_script(&assessments);
        assert_eq!(common::to_value(&script), c["script"], "{name}");
        if name.starts_with("pipeline/") {
            pipeline += 1;
        }
    }
    assert_eq!(pipeline, 12, "6 profile variants x 2 fixture properties");
}

#[test]
fn extract_and_describe_match_python() {
    let doc = g("part4_comms.json");
    let cases = doc["findings"].as_array().unwrap();
    assert!(cases.len() >= 150, "{}", cases.len());
    let (mut numbers, mut bools, mut texts, mut unclear) = (0, 0, 0, 0);
    for c in cases {
        let q = CallQuestion::from_json_value(c["question"].clone()).unwrap();
        let answer = s(&c["answer"]);
        let f = extract(&q, answer);
        assert_eq!(common::to_value(&f), c["finding"], "{answer:?}");
        assert_eq!(describe(&f), s(&c["describe"]), "{answer:?}");
        assert_eq!(f.classification, "OWNER_REPORTED");
        match &f.value {
            Value::Null => unclear += 1,
            Value::Bool(_) => bools += 1,
            Value::Number(_) => numbers += 1,
            _ => texts += 1,
        }
    }
    eprintln!("findings: {numbers} numbers, {bools} yes/no, {texts} texts, {unclear} unclear");
    assert!(numbers >= 40 && bools >= 30 && texts >= 10 && unclear >= 40);
    for c in doc["describe"].as_array().unwrap() {
        let f = StructuredFinding::from_json_value(c["finding"].clone()).unwrap();
        assert_eq!(describe(&f), s(&c["describe"]), "{}", c["finding"]);
    }
}

#[test]
fn detect_escalation_matches_python() {
    let doc = g("part4_comms.json");
    let cases = doc["escalation"].as_array().unwrap();
    assert!(cases.len() >= 200, "{}", cases.len());
    let mut hits = 0;
    for c in cases {
        let u = s(&c["utterance"]);
        let ours = detect_escalation(u).map(|r| r.as_str().to_owned());
        assert_eq!(ours.as_deref(), c["reason"].as_str(), "{u:?}");
        hits += usize::from(ours.is_some());
    }
    assert!(hits >= 80 && hits <= cases.len() - 60, "{hits}");
}

/// `[[key, value], ...]` in order.
fn pairs(v: &Value) -> IndexMap<String, Value> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|p| (s(&p[0]).to_owned(), p[1].clone()))
        .collect()
}

#[test]
fn client_state_matches_python() {
    let doc = g("part4_comms.json");
    let mut nested_order = 0;
    for c in doc["client_state"]["encode"].as_array().unwrap() {
        let state = pairs(&c["state_pairs"]);
        let ours = encode_client_state(&state);
        if ours != s(&c["encoded"]) {
            // Documented limitation: a nested object is written in serde_json's sorted key order
            // (no `preserve_order` feature in the workspace); Python keeps insertion order. Same
            // content, and the call flow's client state is flat.
            let b64 = base64::engine::general_purpose::STANDARD;
            let a: Value = serde_json::from_slice(&b64.decode(&ours).unwrap()).unwrap();
            let b: Value = serde_json::from_slice(&b64.decode(s(&c["encoded"])).unwrap()).unwrap();
            assert_eq!(a, b, "{}", c["state_pairs"]);
            assert!(state.values().any(Value::is_object), "{}", c["state_pairs"]);
            nested_order += 1;
        }
        assert_eq!(decode_client_state(Some(s(&c["encoded"]))), state);
    }
    let mut unrepresentable = 0;
    for c in doc["client_state"]["decode"].as_array().unwrap() {
        assert!(
            c.get("raises").is_none(),
            "Python never raises on a str: {c}"
        );
        let decoded = decode_client_state(c["value"].as_str());
        if let Some(text) = c["decoded_unrepresentable"].as_str() {
            // Documented deviation: Python parses NaN/Infinity literals and lone surrogates;
            // Rust gives {}.
            assert!(decoded.is_empty(), "{text}");
            unrepresentable += 1;
            continue;
        }
        let theirs = pairs(&c["decoded_pairs"]);
        assert_eq!(decoded, theirs, "{}", c["value"]);
        assert_eq!(
            decoded.keys().collect::<Vec<_>>(),
            theirs.keys().collect::<Vec<_>>(),
            "key order"
        );
    }
    assert_eq!(unrepresentable, 2);
    assert_eq!(nested_order, 1);
}

/// Python's `json.dumps(v, sort_keys=True, separators=(",", ":"), default=str)`, the
/// `payload_hash` input (the same rules as ss-server's `pyjson::dumps_canonical`).
fn dumps_canonical(v: &Value, out: &mut String) {
    match v {
        Value::Object(m) => {
            let mut keys: Vec<&String> = m.keys().collect();
            keys.sort_by(|a, b| a.as_bytes().cmp(b.as_bytes()));
            out.push('{');
            for (i, k) in keys.into_iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                py::json_push_str(out, k);
                out.push(':');
                dumps_canonical(&m[k], out);
            }
            out.push('}');
        }
        Value::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                dumps_canonical(item, out);
            }
            out.push(']');
        }
        other => py::json_push_compact(out, other),
    }
}

#[test]
fn call_payload_hashes_like_python() {
    let doc = g("part4_comms.json");
    let cases = doc["call_payload"].as_array().unwrap();
    assert!(cases.len() >= 20);
    for c in cases {
        let project: Uuid = s(&c["project_id"]).parse().unwrap();
        let property: Option<Uuid> = c["property_id"].as_str().map(|p| p.parse().unwrap());
        let recipient: IndexMap<String, String> =
            serde_json::from_value(c["recipient"].clone()).unwrap();
        let payload = call_payload(project, &recipient, property);
        assert_eq!(Value::Object(payload.clone()), c["payload"]);
        let mut canonical = String::new();
        dumps_canonical(&Value::Object(payload), &mut canonical);
        assert_eq!(canonical, s(&c["canonical"]));
        let hash: String = Sha256::digest(canonical.as_bytes())
            .iter()
            .map(|b| format!("{b:02x}"))
            .collect();
        assert_eq!(hash, s(&c["payload_hash"]), "{}", c["recipient"]);
    }
}

