// ---- signatures ---------------------------------------------------------------------------------

fn headers(v: &Value) -> Vec<(String, String)> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|p| (s(&p[0]).to_owned(), s(&p[1]).to_owned()))
        .collect()
}

fn body(v: &Value) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD
        .decode(s(v))
        .unwrap()
}

fn mode(v: &Value) -> WebhookMode {
    match s(v) {
        "live" => WebhookMode::Live,
        _ => WebhookMode::Fixture,
    }
}

fn check(name: &str, ours: Result<VerifiedWebhook, WebhookError>, theirs: &Value) {
    match (ours, theirs.get("ok"), theirs["err"].as_str()) {
        (Ok(v), Some(ok), _) => {
            assert_eq!(v.provider, s(&ok["provider"]), "{name}");
            assert_eq!(v.event_id, s(&ok["event_id"]), "{name}");
            assert_eq!(v.mode.as_str(), s(&ok["mode"]), "{name}");
            assert_eq!(v.is_live_verified(), s(&ok["mode"]) == "live", "{name}");
        }
        (Err(WebhookError::InvalidSignature(m)), None, Some("INVALID_SIGNATURE")) => {
            assert_eq!(m, s(&theirs["message"]), "{name}")
        }
        (Err(e @ WebhookError::Unhandled(_)), None, Some("UNHANDLED")) => {
            assert_eq!(e.status_code(), 500, "{name}");
            assert_eq!(e.error_code(), "INTERNAL_ERROR");
        }
        (ours, _, _) => panic!("{name}: Rust {ours:?}, Python {theirs}"),
    }
}

#[test]
fn standard_webhooks_match_python() {
    let doc = g("part4_signatures.json");
    let cases = doc["standard_webhooks"].as_array().unwrap();
    assert!(cases.len() >= 40);
    let mut accepted = 0;
    for c in cases {
        let name = s(&c["name"]);
        let ours = verify_standard_webhook(
            s(&c["provider"]),
            c["secret"].as_str(),
            &headers(&c["headers"]),
            &body(&c["body_b64"]),
            mode(&c["mode"]),
            c["now"].as_f64(),
        );
        accepted += usize::from(ours.is_ok());
        check(name, ours, &c["result"]);
    }
    assert!(accepted >= 15 && accepted <= cases.len() - 20, "{accepted}");
    for c in doc["standard_webhooks_sign"].as_array().unwrap() {
        let ours = standard_webhooks_sign(
            s(&c["secret"]),
            s(&c["msg_id"]),
            c["timestamp"].as_i64().unwrap(),
            &body(&c["body_b64"]),
        );
        match (ours, c["signature"].as_str()) {
            (Ok(sig), Some(theirs)) => assert_eq!(sig, theirs),
            (Err(_), None) => assert!(c["raises"].is_string()),
            (o, t) => panic!("sign {}: Rust {o:?}, Python {t:?}", c["secret"]),
        }
    }
}

